def proc_alive_independent(pid):
    """Liveness check that does NOT go through the artifact's is_alive().
    Reaps any zombie first, then probes with signal 0."""
    try:
        rpid, _ = os.waitpid(pid, os.WNOHANG)
        if rpid == pid:
            return False  # exited and reaped
    except ChildProcessError:
        pass
    except OSError:
        pass
    try:
        os.kill(pid, 0)
        return True
    except ProcessLookupError:
        return False
    except PermissionError:
        return True

# Cross-check is_alive() against an independent probe on the real pid, so a
# faulty is_alive() that always returns True cannot pass.
real_pid = t._pid
check("is_alive() agrees with independent liveness probe (alive now)",
      t.is_alive() is True and proc_alive_independent(real_pid) is True,
      f"pid={real_pid}")

